public static object GetSystemInfoNative(string computerName = ".")
{
    var scope = new System.Management.ManagementScope($"\\\\{computerName}\\root\\cimv2");
    scope.Connect();
    var searcher = new System.Management.ManagementObjectSearcher(scope, new System.Management.SelectQuery("SELECT * FROM Win32_ComputerSystem"));
    var sys = searcher.Get().Cast<System.Management.ManagementObject>().FirstOrDefault();
    return new {
        Manufacturer = sys["Manufacturer"],
        Model = sys["Model"],
        TotalRAM_GB = (ulong)sys["TotalPhysicalMemory"] / (1024*1024*1024),
        Processors = sys["NumberOfProcessors"]
    };
}

public static bool SetRegistryKeyNative(string keyPath, string valueName, object value, string valueKind = "String")
{
    using (var baseKey = Microsoft.Win32.RegistryKey.OpenBaseKey(Microsoft.Win32.RegistryHive.LocalMachine, Microsoft.Win32.RegistryView.Registry64))
    using (var key = baseKey.CreateSubKey(keyPath.Replace("HKLM:\\", ""), Microsoft.Win32.RegistryKeyPermissionCheck.ReadWriteSubTree))
    {
        var kind = (Microsoft.Win32.RegistryValueKind)System.Enum.Parse(typeof(Microsoft.Win32.RegistryValueKind), valueKind);
        key.SetValue(valueName, value, kind);
        return true;
    }
}

function Invoke-RemoteCommand {
    param([string[]]$ComputerNames, [ScriptBlock]$ScriptBlock, [string]$Command, [PSCredential]$Credential, [int]$ThrottleLimit = 25)
    $results = @()
    $sessionOptions = New-PSSessionOption -SkipCACheck -SkipCNCheck
    foreach ($comp in $ComputerNames) {
        try {
            $session = New-PSSession -ComputerName $comp -Credential $Credential -SessionOption $sessionOptions -ErrorAction Stop
            if ($ScriptBlock) {
                $out = Invoke-Command -Session $session -ScriptBlock $ScriptBlock -ErrorAction Stop
            } else {
                $out = Invoke-Command -Session $session -ScriptBlock { param($c); cmd /c $c } -ArgumentList $Command
            }
            $results += [PSCustomObject]@{ ComputerName=$comp; Success=$true; Output=$out; Error=$null }
            Remove-PSSession $session
        } catch {
            $results += [PSCustomObject]@{ ComputerName=$comp; Success=$false; Output=$null; Error=$_.Exception.Message }
        }
    }
    return $results
}

function Copy-FileToRemote {
    param([string]$SourcePath, [string]$DestinationPath, [string[]]$ComputerNames, [PSCredential]$Credential, [switch]$UseBITS)
    $results = @()
    foreach ($comp in $ComputerNames) {
        try {
            $dest = "\\$comp\$( $DestinationPath -replace '^[A-Z]:', '')"
            if ($UseBITS) {
                Start-BitsTransfer -Source $SourcePath -Destination $dest -Credential $Credential
            } else {
                Copy-Item -Path $SourcePath -Destination $dest -Recurse -Force -Credential $Credential
            }
            $results += [PSCustomObject]@{ Computer=$comp; Success=$true; Path=$dest }
        } catch {
            $results += [PSCustomObject]@{ Computer=$comp; Success=$false; Error=$_.Exception.Message }
        }
    }
    return $results
}

function New-RemoteScheduledTask {
    param([string[]]$ComputerNames, [string]$TaskName, [string]$Action, [string]$TriggerType = 'Daily', [PSCredential]$Credential)
    $script = {
        param($Name, $Act, $Trig)
        $task = New-ScheduledTaskAction -Execute $Act
        $trigger = switch($Trig) { 'Daily' { New-ScheduledTaskTrigger -Daily -At 2am }; 'AtLogon' { New-ScheduledTaskTrigger -AtLogon } }
        Register-ScheduledTask -TaskName $Name -Action $task -Trigger $trigger -User $using:Credential.UserName -Password $using:Credential.GetNetworkCredential().Password -Force
    }
    Invoke-RemoteCommand -ComputerNames $ComputerNames -ScriptBlock $script -Credential $Credential
}

function Deploy-SoftwareRemote {
    param([string[]]$ComputerNames, [string]$InstallerPath, [string]$Arguments = '/quiet /norestart', [PSCredential]$Credential)
    $results = Invoke-RemoteCommand -ComputerNames $ComputerNames -ScriptBlock {
        param($Path, $Args)
        Start-Process -FilePath $Path -ArgumentList $Args -Wait -NoNewWindow
        [PSCustomObject]@{ Installer=$Path; ExitCode=$LASTEXITCODE }
    } -Credential $Credential
    return $results
}
